const $=id=>document.getElementById(id);
let game={time:900,home:0,guest:0,period:1,running:false,enabled:true,pen:{home:[],guest:[]}}, edit=null, digits='', timeout=null, sound=true, last=performance.now(), audio;
function fmt(t){t=Math.max(0,t);if(t<60&&t>0)return t.toFixed(1).padStart(4,'0');let n=Math.ceil(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function log(message){const li=document.createElement('li'),t=document.createElement('time');t.textContent=fmt(game.time);li.append(t,document.createTextNode(message));$('log').prepend(li);while($('log').children.length>25)$('log').lastChild.remove()}
function tell(message){$('prompt').textContent=message}
function render(){ $('clock').textContent=timeout===null?fmt(game.time):fmt(timeout);for(const side of ['home','guest']){$(side).textContent=game[side];$(side==='home'?'hp':'gp').textContent=game.pen[side].map(p=>'#'+p.player+'  '+fmt(p.remaining)).join('\n')||'—  —:——'}$('period').textContent=game.period;$('status').textContent=timeout!==null?'● TIME OUT':game.running?'● CLOCK RUNNING':'● CLOCK STOPPED';$('status').style.color=game.running?'#47804b':'#98703a';$('penstate').textContent='PENALTY CLOCKS '+(game.enabled?'ON':'OFF');if(!edit)$('entry').textContent=timeout!==null?'TIME OUT '+fmt(timeout):'MAIN CLOCK '+fmt(game.time);else $('entry').textContent=digits||'_' }
const hornAudio=new RinkHorn(()=>tell('AUDIO BLOCKED · CHECK BROWSER SOUND'));
function horn(){document.body.classList.add('honking');setTimeout(()=>document.body.classList.remove('honking'),700);tell(sound?'HORN':'HORN · MUTED — TAP SOUND OFF TO ENABLE');if(sound)hornAudio.pulse();}

function cancel(){edit=null;digits='';tell('HOCKEY · READY');render()}
function begin(type,side){if(game.running||timeout!==null){tell('STOP CLOCK BEFORE EDITING');return}edit={type,side};digits='';tell(type==='time'?'SET MAIN CLOCK · MMSS':type==='delete'?'DELETE PENALTY · SLOT 1 OR 2':'PLAYER NUMBER · 0–99');render()}
function emit(){}
function enter(){if(!edit||!digits)return;const n=Number(digits);if(edit.type==='player'){if(n>99){tell('PLAYER NUMBER MUST BE 0–99');return}edit.player=n;edit.type='penalty';digits='';tell('PENALTY TIME · MMSS (200 = 2 MIN)');render();return}if(edit.type==='time'||edit.type==='penalty'){let secs=n%100,minutes=Math.floor(n/100);if(secs>59||minutes>99||n===0&&edit.type==='penalty'){tell('INVALID TIME · USE MMSS, SECONDS 00–59');return}if(edit.type==='time'){game.time=minutes*60+secs;log('Main clock set to '+fmt(game.time))}else{game.pen[edit.side].push({player:edit.player,remaining:minutes*60+secs});log(edit.side+' #'+edit.player+' penalty '+fmt(minutes*60+secs));}const event=edit.type==='time'?'set':'penalty';cancel();emit(event);return}if(edit.type==='delete'){if(n<1||n>game.pen[edit.side].length){tell('SELECT AN OCCUPIED SLOT: 1 OR 2');return}const [p]=game.pen[edit.side].splice(n-1,1);log(edit.side+' #'+p.player+' penalty deleted');cancel();emit('delete')}}
function num(n){if(edit&&digits.length<(edit.type==='player'||edit.type==='delete'?2:4)){digits+=n;render()}}
function act(action){const [a,side,delta]=action.split(':');if(a==='start'){start();return;}if(a==='stop'){stop();return;}if(a==='stat'){const kind=delta,change=Number(action.split(':')[3]);game.stats??={};const k=side+kind;game.stats[k]=Math.max(0,(game.stats[k]||0)+change);log(side+' '+kind+' '+game.stats[k]);}if(a==='clearall'){game.pen[side]=[];log(side+' penalties cleared');}if(a==='set')begin('time');if(a==='pen'){if(game.pen[side].length>=2){tell('TWO SLOTS FULL · RESOLVE BEFORE ADDING');return}begin('player',side)}if(a==='delete')begin('delete',side);if(a==='score'){game[side]=Math.max(0,Math.min(99,game[side]+Number(delta)));log(side+' score '+game[side]);emit('score')}if(a==='period'){if(game.running||timeout!==null){tell('STOP CLOCK BEFORE CHANGING PERIOD');return}game.period=game.period>=9?1:game.period+1;log('Period '+game.period)}if(a==='penon'||a==='penoff'){game.enabled=a==='penon';log('Penalty clocks '+(game.enabled?'enabled':'disabled'));emit(a)}if(a==='horn')horn();if(a==='timeout'){if(edit){tell('FINISH OR CANCEL ENTRY FIRST');return}if(timeout!==null){timeout=null;log('Time out ended')}else{game.running=false;timeout=30;log('30-second time out started')}}render()}
function start(){if(edit){tell('FINISH OR CANCEL ENTRY FIRST');return}if(timeout!==null){tell('END TIME OUT BEFORE STARTING');return}if(game.time<=0){tell('SET MAIN CLOCK FIRST');return}if(!game.running){game.running=true;last=performance.now();log('Clock started');emit('start')}render()}
function stop(){if(game.running){game.running=false;log('Whistle · clock stopped')}emit('stop');render()}
function reset(){game={time:Number($('length').value),home:0,guest:0,period:1,running:false,enabled:true,pen:{home:[],guest:[]}};timeout=null;cancel();$('log').replaceChildren();log('New practice game');last=performance.now()}
for(const n of ['7','8','9','4','5','6','1','2','3','CLEAR','0','ENTER']){const b=document.createElement('button');b.textContent=n;b.onclick=()=>n==='ENTER'?enter():n==='CLEAR'?(digits?(digits='',render()):cancel()):num(n);$('keypad').append(b)}
document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>act(b.dataset.act));$('length').onchange=()=>tell('PERIOD LENGTH APPLIES ON RESET');$('sound').onclick=()=>{sound=!sound;hornAudio.setMuted(!sound);$('sound').setAttribute('aria-pressed',String(sound));$('sound').textContent='Sound '+(sound?'on':'off');if(sound)horn()};
document.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA','BUTTON'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();game.running?stop():start()}else if(e.key.toLowerCase()==='h')horn();else if(e.key==='Enter')enter();else if(e.key==='Escape')cancel();else if(e.key==='Backspace'){e.preventDefault();digits=digits.slice(0,-1);render()}else if(/^\d$/.test(e.key))num(e.key)});
setInterval(()=>{const now=performance.now(),dt=(now-last)/1000*Number($('speed').value);last=now;if(timeout!==null){timeout=Math.max(0,timeout-dt);if(timeout===0){timeout=null;horn();log('Time out complete')}}else if(game.running){const elapsed=Math.min(dt,game.time);game.time=Math.max(0,game.time-elapsed);if(game.enabled)for(const side of ['home','guest']){for(const p of game.pen[side])p.remaining=Math.max(0,p.remaining-elapsed);game.pen[side]=game.pen[side].filter(p=>{if(p.remaining<=0){log(side+' #'+p.player+' penalty expired');return false}return true})}if(game.time===0){game.running=false;horn();log('Period ended')}}render()},50);log('Practice console ready');render();

document.querySelector('a[href="index.html"]').setAttribute("aria-current","page");

document.addEventListener('pointerdown',()=>{if(sound)hornAudio.unlock().catch(()=>{});},{once:true});
document.addEventListener('keydown',()=>{if(sound)hornAudio.unlock().catch(()=>{});},{once:true});

// Observe actual console actions after state changes, including keyboard input.
const trainingState=()=>({model:game,edit:edit,timeout:timeout,sound,speed:Number($('speed').value),length:Number($('length').value),setTimeout:value=>{timeout=value;},setSound:value=>{sound=value;hornAudio.setMuted(!sound);$('sound').setAttribute('aria-pressed',String(sound));$('sound').textContent='Sound '+(sound?'on':'off');}});
const training=new RinkTutorials({profile:'dak',getState:trainingState,resetScenario:()=>{$('length').value='900';$('speed').value='1';reset();trainingState().setSound(true);last=performance.now();},onRender:render,log});
for(const name of ['act','enter','num','cancel','start','stop']){const original=({act,enter,num,cancel,start,stop})[name];const wrapped=(...args)=>{const result=original(...args);training.observe('key:'+(name==='act'?args[0]:name==='num'?args[0]:name));return result;};if(name==='act')act=wrapped;if(name==='enter')enter=wrapped;if(name==='num')num=wrapped;if(name==='cancel')cancel=wrapped;if(name==='start')start=wrapped;if(name==='stop')stop=wrapped;}
for(const button of $('keypad').querySelectorAll('button')){const original=button.onclick;button.onclick=event=>{original(event);training.observe('key:'+button.textContent.toLowerCase());};}
$('start').onclick=()=>start();$('stop').onclick=()=>stop();
for(const id of ['sound','length','speed']){const element=$(id),property=id==='sound'?'onclick':'onchange',original=element[property];element[property]=event=>{original?.(event);training.observe('ui:'+id);};}
$('reset').onclick=()=>{if(confirm('Reset clock, scores and penalties?')){reset();training.observe('ui:reset');render();}};
document.addEventListener('keydown',event=>{if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(event.target.tagName))return;if(event.code==='Space')training.observe('keyboard:Space');if(event.key.toLowerCase()==='h')training.observe('keyboard:h');});
setInterval(()=>training.observe('tick'),50);
